var minOperations = function(target, arr) {
    const pos = new Map();
    for (let i = 0; i < target.length; ++i) {
        pos.set(target[i], i);
    }
    const mapped = [];
    for (const x of arr) {
        if (pos.has(x)) mapped.push(pos.get(x));
    }
    const lis = [];
    for (const x of mapped) {
        let low = 0, high = lis.length;
        while (low < high) {
            const mid = Math.floor((low + high) / 2);
            if (lis[mid] < x) low = mid + 1;
            else high = mid;
        }
        if (low === lis.length) lis.push(x);
        else lis[low] = x;
    }
    return target.length - lis.length;
};
